using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests
{
    private static readonly string ContentRoot =
        Path.GetDirectoryName(typeof(QualityEvaluationTests).Assembly.Location)!;

    private static readonly string GoldenPath =
        Path.Combine(ContentRoot, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(ContentRoot, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c.UserMessage, c.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task Evaluate_Quality(string id, string userMessage, List<string> expectedTraits)
    {
        // Arrange: load rubric
        var rubric = await File.ReadAllTextAsync(RubricPath);

        // Act: invoke the agent (placeholder — replace with actual agent call)
        var agentResponse = await InvokeAgentAsync(userMessage);

        // Assert: verify expected traits are present
        Assert.NotNull(agentResponse);
        Assert.False(string.IsNullOrWhiteSpace(agentResponse),
            $"Agent returned empty response for case '{id}'.");
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation via AppHost or HTTP client.
        // This placeholder returns the user message echoed back for scaffolding purposes.
        return Task.FromResult($"[Agent response to: {userMessage}]");
    }

    private record GoldenCase
    {
        public string Id { get; init; } = string.Empty;
        public string UserMessage { get; init; } = string.Empty;
        public List<string> ExpectedTraits { get; init; } = new();
    }
}

